from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[2]

sys.path.insert(
    0,
    str(ROOT),
)


from american_options.ai_assistant import ask


def main() -> None:

    print()
    print("American Option Analytics Assistant")
    print("===================================")
    print(
        "Numerical results are generated by "
        "the deterministic FEM engine."
    )
    print("Type 'quit' to exit.")
    print()

    while True:

        question = input(
            "You: "
        ).strip()

        if question.lower() in {
            "quit",
            "exit",
        }:
            break

        if not question:
            continue

        try:

            answer = ask(
                question
            )

            print()
            print("Assistant:")
            print(answer)
            print()

        except Exception as error:

            print()
            print(
                f"Error: {error}"
            )
            print()


if __name__ == "__main__":
    main()